answers.approach:
use_case = select_one("bounded, reversible activation", owner, risk_budget)
// Do not begin with a universal ontology; agreement is easier around one consequential decision.
terms = inventory_terms(use_case, across=[CRM, CDP, warehouse, ad_platforms])
contracts = define_versioned_terms(terms, SQL_or_rules, source_authority, freshness, exceptions)
// Definitions must be executable and testable, not glossary prose that systems can reinterpret.
entities = map_identities(contracts, confidence_scores, merge_rules, non_merge_rules)
policy = compile_policy(principal, delegated_purpose, fields, rows, actions, consent, expiry)
// Effective access is the intersection across every hop, with deny-by-default and no silent widening.
context = issue_signed_bundle(contracts, policy, lineage, timestamps, quality_metrics)
// Agents need provenance and ambiguity surfaced; conflicting definitions should trigger abstention.
gate = require_preflight(agent_plan, context, expected_audience, side_effects, approval_thresholds)
adapters = isolate_tool_protocols(MCP_and_vendor_APIs, behind="stable internal capability contracts")
// I would not let a moving transport specification become the semantic or authorization boundary.
results = shadow_run(use_case, compare_to=human_baseline, test=[leakage, drift, false_activation])
iterate_or_stop(results, with=[data_owners, security, legal, operators])
// Scale only after evidence; expect organizational disagreement and identity errors to dominate.
